import numpy as np

# Java Random LCG constants
MULT = 0x5DEECE66D
ADD = 0xB
MASK = (1 << 48) - 1

class JavaRandom:
    def __init__(self, seed):
        self.seed = (seed ^ MULT) & MASK

    def nextbits(self, bits):
        self.seed = (self.seed * MULT + ADD) & MASK
        return int(self.seed >> (48 - bits))

    def nextInt(self):
        return self.nextbits(32)

    def clone(self):
        return JavaRandom(self.seed ^ MULT)

# Return next internal state given previous nextInt()
def next_state_from_nextInt(prev_seed):
    # prev_seed: internal state right after nextInt() was generated (after setSeed)
    # Advance the lcg
    return (prev_seed * MULT + ADD) & MASK

def internal_from_nextInt(nextint, candidate_upper16=None):
    # Given a nextInt() output, recover the internal state candidates
    # Only lower 32 bits of output are known
    # Returns all possible 16 high bits
    candidates = []
    nextint = np.uint32(nextint)
    for upper in range(1<<16):
        candidate = (upper << 32) | nextint
        if candidate_upper16 is not None and upper != candidate_upper16:
            continue
        # reverse nextbits
        # skip, not needed for basic filtering & simulation
        candidates.append(candidate)
    return candidates

def roll_color(x):
    n = x & 15
    if n == 0:
        return 'green'
    elif n <= 7:
        return 'red'
    else:
        return 'black'

